include <robotics.scad>
// Ovonic O-50C-2200-2S1P-XT60+TRX pack body (shrink-wrapped soft pack).
// Origin: bottom face centre. Long axis X, lead end at +X, label face up (+Z).
L = 87;   // length, mm (official, ±5)
W = 33;   // width, mm (official, ±2)
H = 18;   // height, mm (official, ±2)
r_long = 3;  // long-edge radius: NOT published, conservative estimate
cuboid([L, W, H], rounding = r_long, edges = "X", anchor = BOT, $fn = 32);
